#!/usr/bin/env node
// Generates sites/words/xcount.js: X (Twitter) weighted post length, ported from
// twitter-text 3.1.0 (Apache-2.0, Copyright Twitter, Inc.). We copy the URL and TLD
// regular expressions verbatim from the npm package and re-implement parseTweet()'s
// counting loop in plain browser JS, so the page doesn't need the 200 KB npm bundle.
//
//   cd _work/words && npm install twitter-text@3.1.0
//   node tests/words/gen-xcount.cjs
//
// The test (tests/words/test.cjs) cross-checks the generated file against the real
// twitter-text package when it's installed in _work/words.
const fs = require('fs');
const path = require('path');
const ROOT = path.resolve(__dirname, '../..');
const NM = path.join(ROOT, '_work/words/node_modules');
const R = (n) => require(path.join(NM, 'twitter-text/dist/regexp', n));
const pkg = require(path.join(NM, 'twitter-text/package.json'));
const cfg = require(path.join(NM, 'twitter-text/dist/configs.js')).defaults;

const GTLD = R('validGTLD').source;
const CCTLD = R('validCCTLD').source;
const tpl = (n) => {
  const s = R(n).source;
  return s.split(GTLD).join('#{G}').split(CCTLD).join('#{C}');
};
const EXTRACT_URL = tpl('extractUrl');
const ASCII_DOMAIN = tpl('validAsciiDomain');
const TCO = R('validTcoUrl').source;
const INVALID_PRE = R('invalidUrlWithoutProtocolPrecedingChars').source;
const J = JSON.stringify;

const out = `/*
  X (Twitter) post length for wordcounter.lol. Runs in your browser only.

  X doesn't count plain characters. A link always counts as ${cfg.transformedURLLength}, an emoji
  counts as 2, and most characters outside Latin, Greek, Cyrillic and common
  punctuation (Chinese, Japanese, Korean and more) count as 2 each.

  This is a port of parseTweet() from twitter-text ${pkg.version}
  (https://github.com/twitter/twitter-text), Copyright 2018 Twitter, Inc.,
  Apache License 2.0 (see /vendor/licenses/twitter-text.LICENSE).
  The URL and domain regular expressions and TLD lists below are copied
  unchanged from that package. Changes: everything is in one file, the loop is
  rewritten without core-js, and emoji are matched with the browser's own
  \\p{RGI_Emoji} (current Unicode) instead of the twemoji-parser package.
  Generated by tests/words/gen-xcount.cjs. Don't edit by hand.
*/
(function () {
  'use strict';
  var GTLD = ${J(GTLD)};
  var CCTLD = ${J(CCTLD)};
  function build(t, flags) { return new RegExp(t.split('#{G}').join(GTLD).split('#{C}').join(CCTLD), flags); }
  var EXTRACT_URL = build(${J(EXTRACT_URL)}, 'gi');
  var ASCII_DOMAIN_SRC = ${J(ASCII_DOMAIN)};
  var ASCII_DOMAIN = build(ASCII_DOMAIN_SRC, 'gi');
  var TCO = new RegExp(${J(TCO)}, 'i');
  var INVALID_PRE = new RegExp(${J(INVALID_PRE)});
  // twitter-text's spacesGroup: a link can never contain one of these.
  var SPACES = /[\\x09-\\x0D\\x20\\x85\\xA0\\u1680\\u180E\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]/;
  var CONFIG = ${J({ maxWeightedTweetLength: cfg.maxWeightedTweetLength, scale: cfg.scale, defaultWeight: cfg.defaultWeight, transformedURLLength: cfg.transformedURLLength, ranges: cfg.ranges })};

  var EMOJI;
  try { EMOJI = new RegExp('\\\\p{RGI_Emoji}', 'gv'); } catch (_) {
    // Older browsers: close enough. Copyright/registered signs only count as emoji with VS16.
    EMOJI = /(?:[\\u00A9\\u00AE]\\uFE0F|[#*0-9]\\uFE0F?\\u20E3|\\p{RI}\\p{RI}|(?![\\u00A9\\u00AE])\\p{Extended_Pictographic}\\uFE0F?\\p{EMod}?(?:\\u200D\\p{Extended_Pictographic}\\uFE0F?\\p{EMod}?)*)/gu;
  }

  // Length of a Punycode-encoded label (RFC 3492), the same thing punycode.js
  // toASCII() produces, which twitter-text uses to check domain labels.
  function punyLen(cps) {
    var n = 128, delta = 0, bias = 72, basic = 0, out = 0, i, m, q, k, t;
    for (i = 0; i < cps.length; i++) if (cps[i] < 128) basic++;
    out = basic + (basic ? 1 : 0);
    var h = basic;
    while (h < cps.length) {
      m = 0x7FFFFFFF;
      for (i = 0; i < cps.length; i++) if (cps[i] >= n && cps[i] < m) m = cps[i];
      delta += (m - n) * (h + 1);
      n = m;
      for (i = 0; i < cps.length; i++) {
        if (cps[i] < n) delta++;
        if (cps[i] === n) {
          for (q = delta, k = 36; ; k += 36) {
            t = k <= bias ? 1 : k >= bias + 26 ? 26 : k - bias;
            if (q < t) break;
            out++;
            q = Math.floor((q - t) / (36 - t));
          }
          out++;
          bias = adapt(delta, h + 1, h === basic);
          delta = 0;
          h++;
        }
      }
      delta++; n++;
    }
    return out;
  }
  function adapt(delta, numPoints, first) {
    var k = 0;
    delta = first ? Math.floor(delta / 700) : delta >> 1;
    delta += Math.floor(delta / numPoints);
    for (; delta > 455; k += 36) delta = Math.floor(delta / 35);
    return Math.floor(k + 36 * delta / (delta + 38));
  }
  // punycode.toASCII(label).length: it also splits on the other full stops (。．｡).
  function labelLen(label) {
    var parts = label.split(/[\\x2E\\u3002\\uFF0E\\uFF61]/), total = parts.length - 1;
    for (var i = 0; i < parts.length; i++) {
      var p = parts[i];
      if (/^[\\x00-\\x7F]*$/.test(p)) total += p.length;
      else total += 4 + punyLen(Array.from(p, function (c) { return c.codePointAt(0); }));
    }
    return total;
  }
  // twitter-text's idna.toAscii(): every label must encode to 1..63 characters.
  function toAsciiLen(domain) {
    if (domain.substring(0, 4) === 'xn--' && !domain.match(build(ASCII_DOMAIN_SRC, 'gi'))) return 0;
    var labels = domain.split('.'), total = labels.length - 1;
    for (var i = 0; i < labels.length; i++) {
      var n = labelLen(labels[i]);
      if (n < 1 || n > 63) return 0;
      total += n;
    }
    return total;
  }
  function isValidUrl(url, protocol, domain) {
    var a = toAsciiLen(domain);
    if (!a) return false;
    return protocol.length + url.length + a - domain.length <= 4096;
  }

  // extractUrlsWithIndices(text), same output as twitter-text.
  function extractUrls(text) {
    if (!text || text.indexOf('.') < 0) return [];
    var urls = [], m;
    EXTRACT_URL.lastIndex = 0;
    while ((m = EXTRACT_URL.exec(text))) {
      var before = m[2] || '', url = m[3], protocol = m[4], domain = m[5], path = m[7];
      var end = EXTRACT_URL.lastIndex, start = end - url.length;
      if (!isValidUrl(url, protocol || 'https://', domain)) continue;
      if (!protocol) {
        if (INVALID_PRE.test(before)) continue;
        var lastUrl = null, asciiEnd = 0;
        domain.replace(ASCII_DOMAIN, function (ascii) {
          var s = domain.indexOf(ascii, asciiEnd);
          asciiEnd = s + ascii.length;
          lastUrl = { url: ascii, indices: [start + s, start + asciiEnd] };
          urls.push(lastUrl);
          return ascii;
        });
        if (lastUrl == null) continue;
        if (path) { lastUrl.url = url.replace(domain, lastUrl.url); lastUrl.indices[1] = end; }
      } else {
        var t = TCO.exec(url);
        if (t) {
          if (t[1] && t[1].length > 40) continue;
          url = t[0]; end = start + url.length;
        }
        urls.push({ url: url, indices: [start, end] });
      }
    }
    return urls;
  }

  // Links never span spaces, and every link has a dot followed by a letter (the start
  // of its top-level domain). So scanning only the space-separated chunks that have
  // one gives the same result as scanning the whole text, and it's much faster.
  var DOT_LETTER = /\\.\\p{L}/u;
  function extractUrlsFast(text) {
    if (!DOT_LETTER.test(text)) return [];
    if (text.length < 2000) return extractUrls(text);
    var out = [], i = 0, n = text.length;
    while (i < n) {
      while (i < n && SPACES.test(text[i])) i++;
      var s = i;
      while (i < n && !SPACES.test(text[i])) i++;
      if (i > s) {
        var chunk = text.slice(s, i);
        if (DOT_LETTER.test(chunk)) {
          var found = extractUrls(chunk);
          for (var k = 0; k < found.length; k++) {
            out.push({ url: found[k].url, indices: [found[k].indices[0] + s, found[k].indices[1] + s] });
          }
        }
      }
    }
    return out;
  }

  function weightOf(code) {
    var r = CONFIG.ranges;
    for (var i = 0; i < r.length; i++) if (code >= r[i].start && code <= r[i].end) return r[i].weight;
    return CONFIG.defaultWeight;
  }

  // parseTweet(text).weightedLength
  function xLength(text) {
    var t = typeof text.normalize === 'function' ? text.normalize() : text;
    var urlAt = Object.create(null), emojiAt = Object.create(null), m, i;
    var urls = extractUrlsFast(t);
    for (i = 0; i < urls.length; i++) urlAt[urls[i].indices[0]] = urls[i].url.length;
    if (/[^\\x00-\\x7F]/.test(t)) {
      EMOJI.lastIndex = 0;
      while ((m = EMOJI.exec(t))) emojiAt[m.index] = m[0].length;
    }
    var w = 0, len = t.length;
    for (i = 0; i < len; i++) {
      if (urlAt[i]) { w += CONFIG.transformedURLLength * CONFIG.scale; i += urlAt[i] - 1; }
      else if (emojiAt[i]) { w += CONFIG.defaultWeight; i += emojiAt[i] - 1; }
      else {
        var c = t.charCodeAt(i);
        if (c >= 0xD800 && c <= 0xDBFF && i < len - 1) {
          var d = t.charCodeAt(i + 1);
          if (d >= 0xDC00 && d <= 0xDFFF) { i++; c = d; }
        }
        w += weightOf(c);
      }
    }
    return { weightedLength: w / CONFIG.scale, urls: urls.length, max: CONFIG.maxWeightedTweetLength };
  }

  var api = { xLength: xLength, extractUrls: extractUrls, extractUrlsFast: extractUrlsFast };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else self.xcount = api;
})();
`;
fs.writeFileSync(path.join(ROOT, 'sites/words/xcount.js'), out);
console.log('wrote sites/words/xcount.js', out.length, 'bytes');
